  Grid MixedChoice(ComboBox combo,string text){var host=new Grid();host.Children.Add(combo);var hint=new TextBlock{Text=text,Margin=new Thickness(12,0,24,0),VerticalAlignment=VerticalAlignment.Center,IsHitTestVisible=false,FontSize=12};hint.SetResourceReference(TextBlock.ForegroundProperty,"Muted");var style=new Style(typeof(TextBlock));style.Setters.Add(new Setter(UIElement.VisibilityProperty,Visibility.Collapsed));var trigger=new DataTrigger{Binding=new System.Windows.Data.Binding("SelectedIndex"){Source=combo},Value=-1};trigger.Setters.Add(new Setter(UIElement.VisibilityProperty,Visibility.Visible));style.Triggers.Add(trigger);hint.Style=style;host.Children.Add(hint);return host;}
  ComboBoxItem WidthChoice(double width){var row=new StackPanel{Orientation=Orientation.Horizontal};double sampleWidth=Math.Min(12,width);var sample=new Border{Width=24,Height=sampleWidth,CornerRadius=new CornerRadius(sampleWidth/2),Margin=new Thickness(0,0,8,0),VerticalAlignment=VerticalAlignment.Center};sample.SetResourceReference(Border.BackgroundProperty,"Text");row.Children.Add(sample);row.Children.Add(new TextBlock{Text=width.ToString("0.##",CultureInfo.InvariantCulture)+" px",VerticalAlignment=VerticalAlignment.Center});return new ComboBoxItem{Content=row,Tag=width};}
  List<FreeCanvasItem> SelectedStyleItems(){return document==null?new List<FreeCanvasItem>():document.Items.Where(i=>selected.Contains(i.Id)&&(i.IsDrawing||i.Kind=="text")).ToList();}
  bool StyleReady {get{return !closed&&document!=null&&!importing&&!materializing;}}
  void ApplyStyle(List<FreeCanvasItem> targets,Action<FreeCanvasItem> edit){if(targets.Count==0)return;FinishGesture();var previous=targets.Select(i=>i.Copy()).ToList();foreach(var item in targets)edit(item);PushUndo(()=>RestoreGeometry(previous));Changed();}
  void ApplyInk(string color){if(!StyleReady||!inkColors.IsEnabled||!FreeCanvasStore.ValidColor(color))return;var targets=SelectedStyleItems().Where(i=>i.Color!=color).ToList();if(targets.Count>0)ApplyStyle(targets,i=>i.Color=color);else if(selected.Count==0&&(IsDrawingMode(mode)||mode=="text")){drawingColor=color;Render();}}
  void ApplyWidth(double screenWidth){if(!StyleReady||!strokeWidths.IsEnabled||!FreeCanvasStore.Finite(screenWidth)||screenWidth<=0)return;double width=Math.Max(.25,Math.Min(100,screenWidth/view.Zoom));var targets=SelectedStyleItems().Where(i=>i.IsDrawing&&Math.Abs(i.Stroke-width)>.000001).ToList();if(targets.Count>0)ApplyStyle(targets,i=>i.Stroke=width);else if(selected.Count==0&&IsDrawingMode(mode)){drawingWidth=screenWidth;Render();}}
  void ApplyLineType(string kind){if(!StyleReady||!lineTypes.IsEnabled||(kind!="line"&&kind!="arrow"))return;var targets=SelectedStyleItems().Where(i=>(i.Kind=="line"||i.Kind=="arrow")&&i.Kind!=kind).ToList();if(targets.Count>0)ApplyStyle(targets,i=>i.Kind=kind);}
  void SyncDrawingStyle(){
   if(inkColors==null||strokeWidths==null||lineTypes==null||styleChange)return;styleChange=true;try{
    var items=SelectedStyleItems();var drawings=items.Where(i=>i.IsDrawing).ToList();var paths=items.Where(i=>i.Kind=="line"||i.Kind=="arrow").ToList();bool next=selected.Count==0&&(IsDrawingMode(mode)||mode=="text");styleContext.Text=items.Count>0?"已选内容 · "+items.Count+" 项":selected.Count>0?"所选内容无需调整":next?"下一笔默认":"选择内容后调整";inkColors.IsEnabled=StyleReady&&(items.Count>0||next);strokeWidths.IsEnabled=StyleReady&&(drawings.Count>0||(next&&IsDrawingMode(mode)));lineTypes.IsEnabled=StyleReady&&paths.Count>0;lineTypes.Visibility=paths.Count>0?Visibility.Visible:Visibility.Collapsed;
    string color=items.Count>0?(items.All(i=>(i.Color??"auto")== (items[0].Color??"auto"))?(items[0].Color??"auto"):null):drawingColor;if(customInk!=null&&(string)customInk.Tag!=color){inkColors.Items.Remove(customInk);customInk=null;}var colorChoice=color==null?null:inkColors.Items.Cast<ComboBoxItem>().FirstOrDefault(i=>(string)i.Tag==color);if(color!=null&&colorChoice==null){var row=new StackPanel{Orientation=Orientation.Horizontal};row.Children.Add(new Border{Width=11,Height=11,CornerRadius=new CornerRadius(5.5),Background=(Brush)new BrushConverter().ConvertFromString(color),Margin=new Thickness(0,0,7,0),VerticalAlignment=VerticalAlignment.Center});row.Children.Add(new TextBlock{Text="自定义"});customInk=new ComboBoxItem{Content=row,Tag=color};inkColors.Items.Add(customInk);colorChoice=customInk;}inkColors.Tag=color==null?"混合颜色":"";inkColors.SelectedItem=colorChoice;
    double? width=drawings.Count>0?(drawings.All(i=>Math.Abs(i.Stroke-drawings[0].Stroke)<.000001)?(double?)(drawings[0].Stroke*view.Zoom):null):Math.Max(.25,Math.Min(100,drawingWidth/view.Zoom))*view.Zoom;if(customWidth!=null&&(!width.HasValue||Math.Abs((double)customWidth.Tag-width.Value)>.000001)){strokeWidths.Items.Remove(customWidth);customWidth=null;}var widthChoice=width.HasValue?strokeWidths.Items.Cast<ComboBoxItem>().FirstOrDefault(i=>Math.Abs((double)i.Tag-width.Value)<.000001):null;if(width.HasValue&&widthChoice==null){customWidth=WidthChoice(width.Value);strokeWidths.Items.Add(customWidth);widthChoice=customWidth;}strokeWidths.Tag=width.HasValue?"":"混合粗细";strokeWidths.SelectedItem=widthChoice;
    string kind=paths.Count>0&&paths.All(i=>i.Kind==paths[0].Kind)?paths[0].Kind:null;lineTypes.Tag=kind==null?"混合线型":"";lineTypes.SelectedItem=kind==null?null:lineTypes.Items.Cast<ComboBoxItem>().First(i=>(string)i.Tag==kind);
   }finally{styleChange=false;}
  }
  void AddMenu(ContextMenu menu,string name,Action action){var item=new MenuItem{Header=name};item.Click+=(s,e)=>action();menu.Items.Add(item);}
  void ThemeChanged(){textLayouts.Clear();UpdateMode();Render();}
  CanvasTextLayout TextLayout(FreeCanvasItem item){
   CanvasTextLayout cached;double width=Math.Max(item.FontSize,item.Width);string color=item.Color??"auto";
   if(!textLayouts.TryGetValue(item.Id,out cached)||cached.Value!=item.Text||cached.Width!=width||cached.FontSize!=item.FontSize||cached.Color!=color){
    var text=new FormattedText(item.Text??"",CultureInfo.CurrentCulture,FlowDirection.LeftToRight,new Typeface("Microsoft YaHei UI"),item.FontSize,Ink(item));text.MaxTextWidth=width;if(text.Width>width){width=text.Width;text.MaxTextWidth=width;}
    cached=new CanvasTextLayout{Value=item.Text,Width=width,FontSize=item.FontSize,Color=color,Text=text,Height=Math.Max(38,text.Height)};textLayouts[item.Id]=cached;textLayoutBuilds++;
   }return cached;
  }
  Rect ItemBounds(FreeCanvasItem item){if(item.Kind=="text"){var layout=TextLayout(item);item.Width=layout.Width;item.Height=layout.Height;}return item.Bounds();}
  void UpdateTextGeometry(){if(document!=null)foreach(var item in document.Items)if(item.Kind=="text")ItemBounds(item);}
  internal FreeCanvasItem AddText(string value,Point world){
   if(document==null||value==null||value.Length>20000)throw new ArgumentException("画布文字无效。");
   var item=new FreeCanvasItem{Id=Guid.NewGuid().ToString("N"),Kind="text",Text=value,Color=drawingColor,FontSize=22,X=world.X,Y=world.Y,Width=320,Height=38};ItemBounds(item);document.Items.Add(item);PushUndo(()=>{document.Items.RemoveAll(i=>i.Id==item.Id);textLayouts.Remove(item.Id);});selected.Clear();selected.Add(item.Id);Changed();return item;
  }
  internal bool EditText(string id,string value){
   var item=document==null?null:document.Items.FirstOrDefault(i=>i.Id==id&&i.Kind=="text");if(item==null||value==null||value==item.Text)return false;if(value.Length>20000)throw new ArgumentException("画布文字无效。");
   ItemBounds(item);var previous=item.Copy();item.Text=value;ItemBounds(item);PushUndo(()=>RestoreGeometry(new List<FreeCanvasItem>{previous}));Changed();return true;
  }
  internal void ResizeCanvasItem(FreeCanvasItem target,FreeCanvasItem original,string corner,Point world){
   FreeCanvasGeometry.Resize(target,original,corner,world,view.Zoom);if(target.Kind=="text"){ItemBounds(target);if(corner.Contains("n"))target.Y=original.Y+original.Height-target.Height;if(corner.Contains("w"))target.X=original.X+original.Width-target.Width;}
  }
  void Mode(string value){if(!toolButtons.ContainsKey(value))return;FinishGesture(false);mode=value;if(IsDrawingMode(mode)||mode=="text")selected.Clear();UpdateMode();surface.Focus();status.Text=value=="select"?"选择 · 拖动空白处框选 · Ctrl 多选 · Del 移除 · 中键拖动画布":value=="pan"?"拖动画布 · 按住左键移动视图 · 滚轮缩放 · V 返回选择":value=="text"?"文字 · 单击放置文字 · 双击已有文字可编辑":value=="stroke"?"画笔 · 按住左键自由绘图 · 上方设置下一笔":"拖动左键绘制 · 上方设置下一笔 · Esc 返回选择";Render();}
  void UpdateMode(){foreach(var pair in toolButtons){bool active=mode==pair.Key;pair.Value.SetResourceReference(Control.BackgroundProperty,active?"AccentSoft":"Panel");pair.Value.SetResourceReference(Control.ForegroundProperty,active?"Accent":"Text");System.Windows.Automation.AutomationProperties.SetItemStatus(pair.Value,active?"已选中":"未选中");}SyncDrawingStyle();if(pinButton!=null){pinButton.ToolTip=Topmost?"取消置顶画布":"置顶画布";System.Windows.Automation.AutomationProperties.SetName(pinButton,Topmost?"取消置顶画布":"置顶画布");pinButton.SetResourceReference(Control.BackgroundProperty,Topmost?"AccentSoft":"Panel");pinButton.SetResourceReference(Control.ForegroundProperty,Topmost?"Accent":"Text");}UpdateCursor();}
  void UpdateCursor(){if(surface!=null)surface.Cursor=panning||spaceDown||mode=="pan"?Cursors.Hand:mode=="select"?Cursors.Arrow:mode=="text"?Cursors.IBeam:mode=="stroke"?Cursors.Pen:Cursors.Cross;}
  void ReloadProjects(string id){
   projectChange=true;try{if(id==null)id=store.LastOpenedId;var list=store.List();if(list.Count==0){var created=NewProject("画布 1");list=store.List();id=created.Id;}projects.ItemsSource=list;var next=list.FirstOrDefault(p=>p.Id==id&&string.IsNullOrEmpty(p.Error))??list.FirstOrDefault(p=>string.IsNullOrEmpty(p.Error));projects.SelectedItem=next;if(next!=null)Load(next.Id);else{document=null;status.Text="现有画布无法读取，原文件已保留。可以新建画布，或从备份恢复。";Render();}}finally{projectChange=false;}
  }
  void SelectProject(){if(projectChange)return;var next=projects.SelectedItem as FreeCanvasProjectInfo;if(next==null)return;if(importing||materializing||!Save(false)){projectChange=true;projects.SelectedItem=((IEnumerable<FreeCanvasProjectInfo>)projects.ItemsSource).FirstOrDefault(p=>document!=null&&p.Id==document.Id);projectChange=false;return;}try{Load(next.Id);}catch(Exception ex){status.Text=ex.Message;projectChange=true;projects.SelectedItem=((IEnumerable<FreeCanvasProjectInfo>)projects.ItemsSource).FirstOrDefault(p=>document!=null&&p.Id==document.Id);projectChange=false;}}
  void Load(string id){var next=store.Load(id);FinishGesture();document=next;view.Zoom=next.Zoom;view.PanX=next.PanX;view.PanY=next.PanY;Topmost=next.Pinned;dirty=saveFailed=false;selected.Clear();undo.Clear();ClearPreviews();UpdateTextGeometry();UpdateTitle();UpdateMode();Render();try{store.RememberOpened(id);}catch(IOException){}catch(UnauthorizedAccessException){}status.Text="拖入图片开始 · 滚轮缩放 · 中键拖动 · 关闭后在主页「画布」找回";}
  void UpdateTitle(){Title=(document==null?"自由画布":document.Name+" · 自由画布")+" · Nook";}
  bool Save(bool show){if(document==null)return true;FinishGesture();if(!dirty){if(show)status.Text="画布已保存";return true;}try{UpdateTextGeometry();document.Zoom=view.Zoom;document.PanX=view.PanX;document.PanY=view.PanY;store.Save(document);bool recovered=saveFailed;dirty=saveFailed=false;saveTimer.Stop();UpdateFeedback();if(show||recovered)status.Text="画布已保存";return true;}catch(Exception ex){saveTimer.Stop();saveFailed=true;UpdateFeedback();status.Text="未能保存："+ex.Message;if(show){if(SaveFailureForTests!=null)SaveFailureForTests(status.Text);else MessageBox.Show(this,status.Text,"Nook · 画布",MessageBoxButton.OK,MessageBoxImage.Warning);}return false;}}
  void Changed(){if(document==null)return;dirty=true;saveTimer.Stop();saveTimer.Start();Render();}
  void PushUndo(Action action){undo.Add(action);if(undo.Count>80)undo.RemoveAt(0);}
  void Undo(){FinishGesture();if(undo.Count==0){status.Text="没有可撤销的操作";return;}var action=undo[undo.Count-1];undo.RemoveAt(undo.Count-1);action();selected.RemoveWhere(id=>!document.Items.Any(i=>i.Id==id));Changed();status.Text="已撤销";}
  bool MayChangeProject(){if(importing||materializing){status.Text="正在保存拖入的图片，请等待完成后再切换项目。";return false;}return Save(false);}
  FreeCanvasDocument NewProject(string name){var created=store.Create(name);if(defaultPinned){created.Pinned=true;store.Save(created);}return created;}
  void CreateProject(){if(!MayChangeProject())return;try{var names=new HashSet<string>(store.List().Select(p=>p.Name),StringComparer.CurrentCultureIgnoreCase);int number=1;while(names.Contains("画布 "+number))number++;var created=NewProject("画布 "+number);ReloadProjects(created.Id);Mode("select");status.Text="已新建空白画布；原画布已保存，可在左上角切换 · ⋯ 重命名";}catch(Exception ex){status.Text=ex.Message;}}
  public void CreateEmptyCanvas(){CreateProject();}
  public bool OpenProject(string id){
   if(closed||string.IsNullOrEmpty(id))return false;if(document!=null&&document.Id==id)return !importing&&!materializing;if(!MayChangeProject())return false;
   try{Load(id);projectChange=true;try{var list=store.List();projects.ItemsSource=list;projects.SelectedItem=list.FirstOrDefault(p=>p.Id==id);}finally{projectChange=false;}Mode("select");return true;}catch(Exception ex){status.Text="未能打开画布："+ex.Message;return false;}
  }
  void RenameProject(){if(document==null||!MayChangeProject())return;string value=Prompt("重命名画布","画布名称",document.Name);if(value==null)return;string old=document.Name;document.Name=value;dirty=true;if(Save(true)){UpdateTitle();ReloadProjects(document.Id);}else document.Name=old;}
  internal bool PrepareCopyProject(){if(closed||document==null)return false;if(importing||materializing){status.Text="请等待拖入的图片保存完成后再复制画布。";return false;}FinishGesture();return true;}
  void SaveProjectAs(){if(!PrepareCopyProject())return;string value=Prompt("复制为新画布","画布名称",document.Name+" 副本");if(value!=null)CopyProject(value);}
  internal bool CopyProject(string name){
   if(!PrepareCopyProject())return false;
   try{bool originalSaved=Save(false);document.Zoom=view.Zoom;document.PanX=view.PanX;document.PanY=view.PanY;var created=store.SaveAs(document,name);dirty=false;ReloadProjects(created.Id);status.Text=originalSaved?"已复制为新画布；原画布保留":"当前编辑已救回到新画布；原画布无法更新，原文件保持不变";return true;}catch(Exception ex){status.Text="复制失败："+ex.Message;return false;}
  }
  void DeleteProject(){if(document==null||!MayChangeProject())return;if(MessageBox.Show(this,"删除画布「"+document.Name+"」？\n只移除这个画布及其独立图片副本，不删除素材库或原文件。可在项目菜单恢复。","删除画布",MessageBoxButton.OKCancel,MessageBoxImage.Warning)!=MessageBoxResult.OK)return;try{store.Trash(document.Id);dirty=false;document=null;ReloadProjects(null);status.Text="画布已移入画布回收目录，可在项目菜单恢复";}catch(Exception ex){status.Text="删除失败："+ex.Message;}}
  void RestoreProject(){if(!MayChangeProject())return;try{string id=store.RestoreLastDeleted();if(id==null){status.Text="没有可恢复的画布";return;}ReloadProjects(id);status.Text="已恢复上次删除的画布";}catch(Exception ex){status.Text="恢复失败："+ex.Message;}}
  string Prompt(string title,string label,string initial){var input=new TextBox{Text=initial,AcceptsReturn=title=="文字",TextWrapping=TextWrapping.Wrap,MaxLength=title=="文字"?20000:120,MinHeight=title=="文字"?100:30,MaxHeight=300,VerticalScrollBarVisibility=ScrollBarVisibility.Auto,Margin=new Thickness(0,9,0,12)};input.SetResourceReference(Control.BackgroundProperty,"Input");input.SetResourceReference(Control.ForegroundProperty,"Text");input.SetResourceReference(Control.BorderBrushProperty,"Border");var content=new StackPanel{Margin=new Thickness(18)};content.Children.Add(new TextBlock{Text=label});content.Children.Add(input);var row=new StackPanel{Orientation=Orientation.Horizontal,HorizontalAlignment=HorizontalAlignment.Right};var dialog=new Window{Title=title,Owner=this,Width=380,SizeToContent=SizeToContent.Height,ResizeMode=ResizeMode.NoResize,WindowStartupLocation=WindowStartupLocation.CenterOwner,Content=content};Theme.Attach(dialog,this);var cancel=Button("取消",()=>dialog.DialogResult=false);cancel.IsCancel=true;var accept=Button("确定",()=>{if(string.IsNullOrWhiteSpace(input.Text))return;dialog.DialogResult=true;});accept.IsDefault=title!="文字";row.Children.Add(cancel);row.Children.Add(accept);content.Children.Add(row);dialog.Loaded+=(s,e)=>{input.Focus();input.SelectAll();};return dialog.ShowDialog()==true?input.Text.Trim():null;}
  void ChooseImages(){var pick=new Microsoft.Win32.OpenFileDialog{Multiselect=true,Filter="图片|*.png;*.jpg;*.jpeg;*.gif;*.bmp;*.tif;*.tiff;*.ico;*.webp;*.avif;*.heic;*.heif;*.psd;*.psb;*.dng;*.cr2;*.cr3;*.nef;*.arw;*.orf;*.rw2;*.raf;*.svg;*.ai"};if(pick.ShowDialog(this)==true)AddImages(pick.FileNames);}
  public async void AddImages(string[] paths){await ImportImagesAsync(paths,null);}
  public bool PrepareExit(){FinishGesture();if(importing||materializing){status.Text="图片仍在保存，请完成后再退出 Nook。";if(IsVisible)Activate();return false;}return Save(true);}
  internal async Task ImportImagesAsync(string[] paths,Point? point){
   if(closed||paths==null||paths.Length==0)return;if(importing||materializing){status.Text="上一批图片仍在保存，请完成后再拖入。";return;}if(document==null){status.Text="请先新建一个画布项目";return;}FinishGesture();importing=true;projects.IsEnabled=false;var added=new List<FreeCanvasItem>();string projectId=document.Id;int errors=0;string lastError="";Point origin=point??view.World(new Point(Math.Max(100,surface.ActualWidth/2),Math.Max(100,surface.ActualHeight/2)));if(!point.HasValue&&document.Items.Count>0){Rect occupied=Rect.Empty;foreach(var item in document.Items)occupied.Union(ItemBounds(item));if(!occupied.IsEmpty)origin=new Point(occupied.Left,occupied.Bottom+40);}double x=origin.X,y=origin.Y,rowHeight=0;int inRow=0;
   try{for(int index=0;index<paths.Length;index++){lifetime.Token.ThrowIfCancellationRequested();status.Text="正在保存图片 "+(index+1)+" / "+paths.Length;try{string source=paths[index];var item=await Task.Run(()=>store.Import(projectId,source,lifetime.Token));if(closed||document.Id!=projectId)return;if(added.Count==0)PushUndo(()=>{foreach(var inserted in added)document.Items.RemoveAll(i=>i.Id==inserted.Id);});item.X=x;item.Y=y;document.Items.Add(item);added.Add(item);x+=item.Width+24;rowHeight=Math.Max(rowHeight,item.Height);if(++inRow>=4){x=origin.X;y+=rowHeight+24;inRow=0;rowHeight=0;}selected.Clear();selected.Add(item.Id);Changed();}catch(OperationCanceledException){throw;}catch(Exception ex){errors++;lastError=ex.Message;}}
    bool aiPreview=added.Any(item=>string.Equals(Path.GetExtension(item.Source),".ai",StringComparison.OrdinalIgnoreCase));status.Text=added.Count>0?"已添加 "+added.Count+" 张图片；副本只保存在此画布"+(aiPreview?" · AI 为首页预览":"")+(errors>0?"，"+errors+" 项失败："+lastError:""):"没有添加图片："+lastError;Save(false);
   }catch(OperationCanceledException){if(!closed)status.Text="已停止添加图片";}finally{importing=false;if(!closed){projects.IsEnabled=true;UpdateFeedback();}}
  }
  void CanvasDragOver(object sender,DragEventArgs e){e.Effects=!importing&&!materializing&&(e.Data.GetDataPresent(DataFormats.FileDrop)||DesktopImageDrop.CanRead(e.Data))?DragDropEffects.Copy:DragDropEffects.None;e.Handled=true;}
  async void CanvasDrop(object sender,DragEventArgs e){e.Handled=true;if(importing||materializing){status.Text="上一张图片仍在保存，请稍后再拖入。";return;}Point point=view.World(e.GetPosition(surface));try{var paths=e.Data.GetDataPresent(DataFormats.FileDrop)?e.Data.GetData(DataFormats.FileDrop)as string[]:null;if(paths!=null){await ImportImagesAsync(paths,point);return;}var payload=DesktopImageDrop.Capture(e.Data);e.Effects=DragDropEffects.Copy;await ImportPayloadAsync(payload,point);}catch(Exception ex){status.Text="未添加图片："+ex.Message;}}
  internal async Task ImportPayloadAsync(DesktopImageDrop payload,Point point){if(closed||payload==null||document==null||importing||materializing)return;string path=null;materializing=true;projects.IsEnabled=false;UpdateFeedback();status.Text="正在保存拖入的图片…";try{await Task.Yield();path=await Task.Run(()=>payload.Stage());materializing=false;await ImportImagesAsync(new[]{path},point);}catch(Exception ex){if(!closed)status.Text="未添加图片："+ex.Message;}finally{materializing=false;DesktopImageDrop.Cleanup(path);if(!closed){projects.IsEnabled=true;UpdateFeedback();}}}
  async void PasteImage(){if(importing||materializing||document==null)return;try{var data=Clipboard.GetDataObject();var paths=data.GetDataPresent(DataFormats.FileDrop)?data.GetData(DataFormats.FileDrop)as string[]:null;if(paths!=null){await ImportImagesAsync(paths,null);return;}if(!DesktopImageDrop.CanRead(data)){status.Text="剪贴板没有图片，可直接拖入图片文件。";return;}var payload=DesktopImageDrop.Capture(data);await ImportPayloadAsync(payload,view.World(new Point(surface.ActualWidth/2,surface.ActualHeight/2)));}catch(Exception ex){status.Text="未粘贴图片："+ex.Message;}}
  internal static bool Editing(DependencyObject target){while(target!=null){if(target is System.Windows.Controls.Primitives.TextBoxBase||target is ComboBox||target is ComboBoxItem)return true;var visual=target as Visual;var parent=visual!=null?VisualTreeHelper.GetParent(visual):null;target=parent??LogicalTreeHelper.GetParent(target);}return false;}
  void Keys(object sender,KeyEventArgs e){if(Editing(e.OriginalSource as DependencyObject)||Editing(Keyboard.FocusedElement as DependencyObject))return;bool control=(Keyboard.Modifiers&ModifierKeys.Control)!=0;if(control&&e.Key==Key.N){CreateProject();e.Handled=true;}else if(control&&e.Key==Key.S){if((Keyboard.Modifiers&ModifierKeys.Shift)!=0)SaveProjectAs();else Save(true);e.Handled=true;}else if(control&&e.Key==Key.V){PasteImage();e.Handled=true;}else if(control&&e.Key==Key.Z){if(!importing&&!materializing)Undo();e.Handled=true;}else if(control&&e.Key==Key.A){if(document!=null){selected.Clear();foreach(var item in document.Items)selected.Add(item.Id);Render();}e.Handled=true;}else if(e.Key==Key.Delete){if(!importing&&!materializing)DeleteSelection();e.Handled=true;}else if(e.Key==Key.Space){spaceDown=true;UpdateCursor();e.Handled=true;}else if(e.Key==Key.Escape){FinishGesture(false);selected.Clear();Mode("select");Render();e.Handled=true;}else if(Keyboard.Modifiers==ModifierKeys.None){string tool=e.Key==Key.V?"select":e.Key==Key.H?"pan":e.Key==Key.B?"stroke":e.Key==Key.L?"line":e.Key==Key.A?"arrow":e.Key==Key.R?"rectangle":e.Key==Key.O?"ellipse":e.Key==Key.T?"text":null;if(tool!=null){Mode(tool);e.Handled=true;}else if(e.Key==Key.F){Fit();e.Handled=true;}}}
  void DeleteSelection(){FinishGesture();if(document==null||selected.Count==0)return;var removed=document.Items.Select((item,index)=>new{Item=item,Index=index}).Where(p=>selected.Contains(p.Item.Id)).ToArray();PushUndo(()=>{foreach(var pair in removed)document.Items.Insert(Math.Min(pair.Index,document.Items.Count),pair.Item);});document.Items.RemoveAll(i=>selected.Contains(i.Id));foreach(var pair in removed)textLayouts.Remove(pair.Item.Id);selected.Clear();Changed();status.Text="已从画布移除；原图和素材库未删除 · Ctrl+Z 撤销";}
  void Fit(){if(document==null)return;FinishGesture();UpdateTextGeometry();view.Fit(document.Items,Math.Max(400,surface.ActualWidth),Math.Max(300,surface.ActualHeight));Changed();status.Text="已适应全部内容";}
  internal void FitAddedImages(){string feedback=status.Text;Fit();status.Text=feedback;Save(false);}
  void Wheel(object sender,MouseWheelEventArgs e){FinishGesture();view.ZoomAt(Math.Pow(1.15,e.Delta/120.0),e.GetPosition(surface));Changed();status.Text="画布 "+Math.Round(view.Zoom*100)+"%";e.Handled=true;}
  static double SegmentDistance(Point point,Point start,Point end){Vector a=point-start,b=end-start;double t=b.LengthSquared<.0001?0:Math.Max(0,Math.Min(1,Vector.Multiply(a,b)/b.LengthSquared));return (a-b*t).Length;}
  bool ArrowHead(FreeCanvasItem item,out Point first,out Point second){Point start=new Point(item.X,item.Y),end=new Point(item.EndX,item.EndY);Vector direction=end-start;first=second=end;if(direction.Length<.0001)return false;double length=Math.Min(Math.Max(9/view.Zoom,item.Stroke*4),direction.Length*.6);direction.Normalize();Vector side=new Vector(-direction.Y,direction.X)*(length*.55);Point back=end-direction*length;first=back+side;second=back-side;return true;}
  FreeCanvasItem Hit(Point world){if(document==null)return null;double margin=6/view.Zoom;for(int i=document.Items.Count-1;i>=0;i--){var item=document.Items[i];double tolerance=margin+Math.Max(0,item.Stroke)/2;Point start=new Point(item.X,item.Y),end=new Point(item.EndX,item.EndY);Rect bounds=ItemBounds(item);
    if(item.Kind=="line"||item.Kind=="arrow"){if(SegmentDistance(world,start,end)<=tolerance)return item;Point a,b;if(item.Kind=="arrow"&&ArrowHead(item,out a,out b)&&(SegmentDistance(world,end,a)<=tolerance||SegmentDistance(world,end,b)<=tolerance))return item;}
    else if(item.Kind=="stroke"){var points=item.Points;if(points==null||points.Count==0)continue;if(points.Count==1&&SegmentDistance(world,new Point(points[0].X,points[0].Y),new Point(points[0].X,points[0].Y))<=tolerance)return item;for(int p=1;p<points.Count;p++)if(SegmentDistance(world,new Point(points[p-1].X,points[p-1].Y),new Point(points[p].X,points[p].Y))<=tolerance)return item;}
    else if(item.Kind=="rectangle"){if(SegmentDistance(world,bounds.TopLeft,bounds.TopRight)<=tolerance||SegmentDistance(world,bounds.TopRight,bounds.BottomRight)<=tolerance||SegmentDistance(world,bounds.BottomRight,bounds.BottomLeft)<=tolerance||SegmentDistance(world,bounds.BottomLeft,bounds.TopLeft)<=tolerance)return item;}
    else if(item.Kind=="ellipse"){double rx=bounds.Width/2,ry=bounds.Height/2;Point center=new Point(bounds.X+rx,bounds.Y+ry);Vector delta=world-center;if(rx>0&&ry>0){double normalized=Math.Sqrt(delta.X*delta.X/(rx*rx)+delta.Y*delta.Y/(ry*ry));if(normalized>.00001&&(delta-delta/normalized).Length<=tolerance)return item;}}
    else if(bounds.Contains(world))return item;
   }return null;}
  string Corner(Point screen,FreeCanvasItem item){if(item==null)return null;if(item.Kind=="line"||item.Kind=="arrow"){if((screen-view.Screen(new Point(item.X,item.Y))).Length<=8)return "start";if((screen-view.Screen(new Point(item.EndX,item.EndY))).Length<=8)return "end";return null;}Rect r=ScreenBounds(item);foreach(var p in new[]{Tuple.Create("nw",r.TopLeft),Tuple.Create("ne",r.TopRight),Tuple.Create("sw",r.BottomLeft),Tuple.Create("se",r.BottomRight)})if(Math.Abs(screen.X-p.Item2.X)<=8&&Math.Abs(screen.Y-p.Item2.Y)<=8)return p.Item1;return null;}
  Rect ScreenBounds(FreeCanvasItem item){var r=ItemBounds(item);if(item.Kind=="arrow"){Point a,b;if(ArrowHead(item,out a,out b)){r.Union(a);r.Union(b);}}return new Rect(view.Screen(r.TopLeft),new Size(r.Width*view.Zoom,r.Height*view.Zoom));}
  void CaptureGesture(){saveTimer.Stop();if(!surface.CaptureMouse())FinishGesture(false);}
  void Down(object sender,MouseButtonEventArgs e){if(document==null||importing||materializing||gesture)return;surface.Focus();if(e.ChangedButton!=MouseButton.Left&&e.ChangedButton!=MouseButton.Middle)return;downScreen=lastScreen=e.GetPosition(surface);downWorld=view.World(downScreen);gestureButton=e.ChangedButton;if(e.ChangedButton==MouseButton.Middle||(e.ChangedButton==MouseButton.Left&&(spaceDown||mode=="pan"))){gesturePanX=view.PanX;gesturePanY=view.PanY;gesture=panning=true;CaptureGesture();UpdateCursor();e.Handled=true;return;}if(e.ChangedButton!=MouseButton.Left)return;
   if(mode=="text"){string value=Prompt("文字","输入画布文字","");if(value!=null){AddText(value,downWorld);Mode("select");}if(dirty&&!saveTimer.IsEnabled)saveTimer.Start();e.Handled=true;return;}
   if(IsDrawingMode(mode)){if(BeginDrawing(mode,downScreen)){CaptureGesture();e.Handled=true;}return;}
   var only=selected.Count==1?document.Items.FirstOrDefault(i=>selected.Contains(i.Id)):null;resizeCorner=Corner(downScreen,only);if(resizeCorner!=null){before=new List<FreeCanvasItem>{only.Copy()};resizing=gesture=true;CaptureGesture();e.Handled=true;return;}
   var hit=Hit(downWorld);bool control=(Keyboard.Modifiers&ModifierKeys.Control)!=0;if(hit!=null&&hit.Kind=="text"&&e.ClickCount==2){string value=Prompt("文字","编辑画布文字",hit.Text);if(value!=null)EditText(hit.Id,value);if(dirty&&!saveTimer.IsEnabled)saveTimer.Start();e.Handled=true;return;}if(hit!=null){if(control){if(selected.Contains(hit.Id))selected.Remove(hit.Id);else selected.Add(hit.Id);}else if(!selected.Contains(hit.Id)){selected.Clear();selected.Add(hit.Id);}before=document.Items.Where(i=>selected.Contains(i.Id)).Select(i=>i.Copy()).ToList();if(before.Count>0){gesture=true;CaptureGesture();}}else{if(!control)selected.Clear();marquee=gesture=true;selectionRect=new Rect(downScreen,downScreen);CaptureGesture();}Render();e.Handled=true;
  }
  static bool IsDrawingMode(string value){return value=="stroke"||value=="line"||value=="arrow"||value=="rectangle"||value=="ellipse";}
  bool BeginDrawing(string kind,Point screen){if(document==null||closed||importing||materializing||!IsDrawingMode(kind)||gesture)return false;Point world=view.World(screen);if(!FreeCanvasStore.Finite(world.X)||!FreeCanvasStore.Finite(world.Y))return false;drawingPointLimit=FreeCanvasStore.MaximumStrokePoints;if(kind=="stroke"){int used=document.Items.Where(i=>i.Kind=="stroke"&&i.Points!=null).Sum(i=>i.Points.Count);drawingPointLimit=Math.Min(drawingPointLimit,FreeCanvasStore.MaximumDocumentPoints-used);if(drawingPointLimit<1){status.Text="这个项目的绘图内容较多，请另建项目继续绘制。";return false;}}downScreen=lastScreen=screen;downWorld=world;gestureButton=MouseButton.Left;saveTimer.Stop();line=new FreeCanvasItem{Id=Guid.NewGuid().ToString("N"),Kind=kind,Color=drawingColor,Stroke=Math.Max(.25,Math.Min(100,drawingWidth/view.Zoom)),X=downWorld.X,Y=downWorld.Y,EndX=downWorld.X,EndY=downWorld.Y};if(kind=="stroke")line.Points=new List<FreeCanvasPoint>{new FreeCanvasPoint{X=downWorld.X,Y=downWorld.Y}};drawing=gesture=true;Render();return true;}
  void UpdateDrawing(Point screen){if(!drawing||line==null)return;Point world=view.World(screen);if(!FreeCanvasStore.Finite(world.X)||!FreeCanvasStore.Finite(world.Y))return;line.EndX=world.X;line.EndY=world.Y;if(line.Kind=="stroke"){var last=line.Points[line.Points.Count-1];if((world-new Point(last.X,last.Y)).Length*view.Zoom>=.75){if(line.Points.Count<drawingPointLimit)line.Points.Add(new FreeCanvasPoint{X=world.X,Y=world.Y});else status.Text="这笔线条较长，请松开后继续绘制。";}}Render();}
  void Move(object sender,MouseEventArgs e){if(document==null)return;Point screen=e.GetPosition(surface);if(!gesture){var only=selected.Count==1?document.Items.FirstOrDefault(i=>selected.Contains(i.Id)):null;string corner=Corner(screen,only);if(mode=="select"&&!spaceDown)surface.Cursor=corner=="nw"||corner=="se"?Cursors.SizeNWSE:corner=="ne"||corner=="sw"?Cursors.SizeNESW:corner=="start"||corner=="end"||Hit(view.World(screen))!=null?Cursors.SizeAll:Cursors.Arrow;return;}UpdateGesture(screen);}
  void UpdateGesture(Point screen){if(!gesture||document==null)return;if(panning){view.PanX+=screen.X-lastScreen.X;view.PanY+=screen.Y-lastScreen.Y;lastScreen=screen;Render();return;}Point world=view.World(screen);
   if(drawing){UpdateDrawing(screen);return;}if(marquee){selectionRect=new Rect(downScreen,screen);Render();return;}
   if(resizing&&before!=null&&before.Count==1){var original=before[0];var target=document.Items.First(i=>i.Id==original.Id);if(resizeCorner=="start"){target.X=world.X;target.Y=world.Y;}else if(resizeCorner=="end"){target.EndX=world.X;target.EndY=world.Y;}else ResizeCanvasItem(target,original,resizeCorner,world);Render();return;}
   if(before!=null){Vector delta=world-downWorld;foreach(var original in before){var target=document.Items.First(i=>i.Id==original.Id);FreeCanvasGeometry.Move(target,original,delta);}Render();}
  }
  void Up(object sender,MouseButtonEventArgs e){if(!gesture||e.ChangedButton!=gestureButton)return;UpdateGesture(e.GetPosition(surface));FinishGesture();e.Handled=true;}
  static bool GeometryChanged(FreeCanvasItem current,FreeCanvasItem original){if(current==null)return false;if(current.X!=original.X||current.Y!=original.Y||current.Width!=original.Width||current.Height!=original.Height||current.EndX!=original.EndX||current.EndY!=original.EndY)return true;if(current.Points==null||original.Points==null)return current.Points!=original.Points;if(current.Points.Count!=original.Points.Count)return true;for(int i=0;i<current.Points.Count;i++)if(current.Points[i].X!=original.Points[i].X||current.Points[i].Y!=original.Points[i].Y)return true;return false;}
  void RestoreGeometry(List<FreeCanvasItem> snapshot){if(snapshot==null||document==null)return;foreach(var original in snapshot){int index=document.Items.FindIndex(i=>i.Id==original.Id);if(index>=0)document.Items[index]=original.Copy();}}
  void FinishGesture(){FinishGesture(true);}
  void FinishGesture(bool commit){if(!gesture)return;gesture=false;if(surface!=null&&surface.IsMouseCaptured)surface.ReleaseMouseCapture();if(document!=null){if(!commit){if(panning){view.PanX=gesturePanX;view.PanY=gesturePanY;}else RestoreGeometry(before);}else if(drawing&&line!=null){bool valid=line.Kind=="stroke"||(line.Kind=="rectangle"||line.Kind=="ellipse"?Math.Abs(line.EndX-line.X)*view.Zoom>=2&&Math.Abs(line.EndY-line.Y)*view.Zoom>=2:(new Point(line.EndX,line.EndY)-new Point(line.X,line.Y)).Length*view.Zoom>=2);if(valid){var inserted=line;document.Items.Add(inserted);PushUndo(()=>document.Items.RemoveAll(i=>i.Id==inserted.Id));selected.Clear();selected.Add(inserted.Id);Changed();}}else if(marquee){foreach(var item in document.Items)if(selectionRect.IntersectsWith(ScreenBounds(item)))selected.Add(item.Id);}else if(panning){Changed();}else if(before!=null&&before.Count>0){var snapshot=before;bool altered=snapshot.Any(i=>GeometryChanged(document.Items.FirstOrDefault(p=>p.Id==i.Id),i));if(altered){PushUndo(()=>RestoreGeometry(snapshot));Changed();}}}panning=resizing=drawing=marquee=false;line=null;before=null;selectionRect=Rect.Empty;if(dirty&&!saveTimer.IsEnabled)saveTimer.Start();UpdateCursor();Render();}
  void UpdateFeedback(){if(undoButton!=null)undoButton.IsEnabled=undo.Count>0&&!importing&&!materializing;string text=saveFailed?"未能保存":dirty?"待保存":"已保存";if(saveFeedback.Text!=text)saveFeedback.Text=text;saveFeedback.SetResourceReference(TextBlock.ForegroundProperty,saveFailed?"Accent":"Muted");}
  void Render(){UpdateFeedback();SyncDrawingStyle();if(surface!=null&&!closed)surface.InvalidateVisual();}
  internal void DeleteForTests(params string[] ids){selected.Clear();foreach(string id in ids)selected.Add(id);DeleteSelection();}
  internal void UndoForTests(){Undo();}
  internal bool SaveForTests(){return Save(false);}
  internal void FitForTests(){Fit();}
  internal void DrawItemForTests(FreeCanvasItem item){ItemBounds(item);document.Items.Add(item);PushUndo(()=>{document.Items.RemoveAll(i=>i.Id==item.Id);textLayouts.Remove(item.Id);});Changed();}
  internal void BeginMoveForTests(string id,Vector delta){var item=document.Items.First(i=>i.Id==id);before=new List<FreeCanvasItem>{item.Copy()};gesture=true;FreeCanvasGeometry.Move(item,before[0],delta);}
  internal void MoveForTests(string id,Vector delta){BeginMoveForTests(id,delta);FinishGesture();}
  internal void ResizeForTests(string id,string corner,Point world){var item=document.Items.First(i=>i.Id==id);before=new List<FreeCanvasItem>{item.Copy()};gesture=resizing=true;ResizeCanvasItem(item,before[0],corner,world);FinishGesture();}
  internal void SelectForTests(params string[] ids){selected.Clear();foreach(string id in ids)if(document!=null&&document.Items.Any(i=>i.Id==id))selected.Add(id);Render();}
  internal bool SavePendingForTests {get{return saveTimer.IsEnabled;}}
  internal bool BeginDrawingForTests(string kind,Point screen){Mode(kind);return BeginDrawing(kind,screen);}
  internal void UpdateDrawingForTests(Point screen){UpdateDrawing(screen);}
  internal void EndDrawingForTests(Point screen){if(!drawing)return;UpdateDrawing(screen);FinishGesture();}
  internal void CancelGestureForTests(){FinishGesture(false);}
  internal FreeCanvasItem HitForTests(Point world){return Hit(world);}
  internal int TextLayoutBuildsForTests {get{return textLayoutBuilds;}}
  internal int TextLayoutCountForTests {get{return textLayouts.Count;}}
  internal void SetDrawingStyleForTests(string color,double width){if(!FreeCanvasStore.ValidColor(color)||!FreeCanvasStore.Finite(width)||width<.25||width>100)throw new ArgumentException("画布笔画样式无效。");drawingColor=color;drawingWidth=width;}
  internal bool ClosedForTests {get{return closed;}}
  void ClosingCanvas(object sender,CancelEventArgs e){if(!PrepareExit()){e.Cancel=true;return;}}
  void DisposeCanvas(){if(closed)return;closed=true;saveTimer.Stop();previewTimer.Stop();lifetime.Cancel();if(previews!=null)previews.Cancel();Theme.Changed-=ThemeChanged;cache.Clear();requested.Clear();failed.Clear();textLayouts.Clear();cacheBytes=0;surface.InvalidateVisual();}
  void ClearPreviews(){generation++;if(previews!=null)previews.Cancel();previews=new CancellationTokenSource();cache.Clear();requested.Clear();failed.Clear();textLayouts.Clear();cacheBytes=0;previewTimer.Stop();}
  Brush Ink(FreeCanvasItem item){if(item.Color=="auto"||string.IsNullOrEmpty(item.Color))return Theme.Brush("Text");return (Brush)new BrushConverter().ConvertFromString(item.Color);}
  void PaintAnnotation(DrawingContext dc,FreeCanvasItem item){
   Brush ink=Ink(item);double width=Math.Max(.5,item.Stroke*view.Zoom);var pen=new Pen(ink,width){StartLineCap=PenLineCap.Round,EndLineCap=PenLineCap.Round,LineJoin=PenLineJoin.Round};Point start=view.Screen(new Point(item.X,item.Y)),end=view.Screen(new Point(item.EndX,item.EndY));
   if(item.Kind=="stroke"){if(item.Points==null||item.Points.Count==0)return;Point first=view.Screen(new Point(item.Points[0].X,item.Points[0].Y));if(item.Points.Count==1){dc.DrawEllipse(ink,null,first,width/2,width/2);return;}var geometry=new StreamGeometry();using(var context=geometry.Open()){context.BeginFigure(first,false,false);for(int i=1;i<item.Points.Count;i++)context.LineTo(view.Screen(new Point(item.Points[i].X,item.Points[i].Y)),true,false);}geometry.Freeze();dc.DrawGeometry(null,pen,geometry);}
   else if(item.Kind=="line"||item.Kind=="arrow"){dc.DrawLine(pen,start,end);Point a,b;if(item.Kind=="arrow"&&ArrowHead(item,out a,out b)){dc.DrawLine(pen,end,view.Screen(a));dc.DrawLine(pen,end,view.Screen(b));}}
   else if(item.Kind=="rectangle")dc.DrawRectangle(null,pen,ScreenBounds(item));
   else if(item.Kind=="ellipse"){Rect bounds=ScreenBounds(item);dc.DrawEllipse(null,pen,new Point(bounds.X+bounds.Width/2,bounds.Y+bounds.Height/2),bounds.Width/2,bounds.Height/2);}
  }
  void PaintHandles(DrawingContext dc,FreeCanvasItem item,Rect screen){IEnumerable<Point> corners=item.Kind=="line"||item.Kind=="arrow"?new[]{view.Screen(new Point(item.X,item.Y)),view.Screen(new Point(item.EndX,item.EndY))}:new[]{screen.TopLeft,screen.TopRight,screen.BottomLeft,screen.BottomRight};foreach(Point corner in corners)dc.DrawRectangle(Theme.Brush("Surface"),new Pen(Theme.Brush("Accent"),2),new Rect(corner.X-4,corner.Y-4,8,8));}
  void Paint(DrawingContext dc){
   dc.DrawRectangle(Theme.Brush("Canvas"),null,new Rect(0,0,Math.Max(0,surface.ActualWidth),Math.Max(0,surface.ActualHeight)));requested.Clear();if(document==null||closed)return;
   var bounds=new Rect(0,0,Math.Max(1,surface.ActualWidth),Math.Max(1,surface.ActualHeight));var visible=new List<FreeCanvasItem>();foreach(var item in document.Items){Rect screen=ScreenBounds(item);double margin=item.IsDrawing?Math.Max(16,item.Stroke*view.Zoom/2+1):16;screen.Inflate(margin,margin);if(screen.IntersectsWith(bounds))visible.Add(item);}long perItem=previewBudget/Math.Max(1,visible.Count(i=>i.Kind=="image"));int budgetSide=Math.Max(1,(int)Math.Sqrt(perItem/4));
   MatrixTransform textTransform=null;dc.PushClip(new RectangleGeometry(bounds));foreach(var item in visible){Rect screen=ScreenBounds(item);if(item.Kind=="image"){
    CanvasPreview preview;int size=Math.Max(1,Math.Min(Math.Min(2048,budgetSide),(int)Math.Ceiling(Math.Max(screen.Width,screen.Height)/128)*128));if(cache.TryGetValue(item.Image,out preview)){preview.Touch=++touch;dc.DrawImage(preview.Image,screen);if((preview.Size<size||preview.Bytes>perItem)&&!failed.Contains(item.Image))requested[item.Image]=size;}else{dc.DrawRectangle(Theme.Brush("Surface"),new Pen(Theme.Brush("Border"),1),screen);if(screen.Width>54&&screen.Height>30)Text(dc,failed.Contains(item.Image)?"图片无法读取":"正在加载…",screen.TopLeft+new Vector(10,10),12,Theme.Brush("Muted"),Math.Max(1,screen.Width-20));if(!failed.Contains(item.Image))requested[item.Image]=size;}
   }else if(item.IsDrawing)PaintAnnotation(dc,item);else{if(textTransform==null)textTransform=new MatrixTransform(view.Zoom,0,0,view.Zoom,view.PanX,view.PanY);dc.PushTransform(textTransform);dc.DrawText(TextLayout(item).Text,new Point(item.X,item.Y));dc.Pop();}
   if(selected.Contains(item.Id)){if(item.Kind=="line"||item.Kind=="arrow"){var pen=new Pen(Theme.Brush("Accent"),1.5){StartLineCap=PenLineCap.Round,EndLineCap=PenLineCap.Round};Point start=view.Screen(new Point(item.X,item.Y)),end=view.Screen(new Point(item.EndX,item.EndY));dc.DrawLine(pen,start,end);Point a,b;if(item.Kind=="arrow"&&ArrowHead(item,out a,out b)){dc.DrawLine(pen,end,view.Screen(a));dc.DrawLine(pen,end,view.Screen(b));}}else dc.DrawRectangle(null,new Pen(Theme.Brush("Accent"),1.5),screen);if(selected.Count==1)PaintHandles(dc,item,screen);}}
   if(drawing&&line!=null)PaintAnnotation(dc,line);if(marquee&&!selectionRect.IsEmpty)dc.DrawRectangle(Theme.Brush("AccentSoft"),new Pen(Theme.Brush("Accent"),1),selectionRect);dc.Pop();
   if(document.Items.Count==0&&!drawing)Text(dc,"拖入图片，或用画笔开始这个画布",new Point(Math.Max(16,(surface.ActualWidth-280)/2),Math.Max(16,surface.ActualHeight/2)),16,Theme.Brush("Muted"),320);
   if(requested.Count>0&&!pumping&&!previewTimer.IsEnabled)previewTimer.Start();
  }
  static void Text(DrawingContext dc,string value,Point point,double size,Brush brush,double width){if(string.IsNullOrEmpty(value)||width<1)return;var text=new FormattedText(value,CultureInfo.CurrentCulture,FlowDirection.LeftToRight,new Typeface("Microsoft YaHei UI"),size,brush);text.MaxTextWidth=Math.Max(1,width);dc.DrawText(text,point);}
  async void PumpPreviews(){if(pumping||closed||document==null)return;pumping=true;int stamp=generation;string project=document.Id;CancellationToken token=previews.Token;
   try{while(!closed&&stamp==generation&&requested.Count>0){var request=requested.First();requested.Remove(request.Key);CanvasPreview existing;if(cache.TryGetValue(request.Key,out existing)&&existing.Size==request.Value)continue;try{string path=store.ImagePath(project,request.Key);int size=request.Value;BitmapSource bitmap=await Task.Run(()=>{int w,h;return FreeCanvasStore.Decode(path,path,size,token,out w,out h);},token);if(closed||stamp!=generation)return;long bytes=(long)bitmap.PixelWidth*bitmap.PixelHeight*4;CanvasPreview old;if(cache.TryGetValue(request.Key,out old)){cacheBytes-=old.Bytes;cache.Remove(request.Key);}while(cacheBytes+bytes>previewBudget&&cache.Count>0){var remove=cache.OrderBy(p=>p.Value.Touch).First();cacheBytes-=remove.Value.Bytes;cache.Remove(remove.Key);}cache[request.Key]=new CanvasPreview{Image=bitmap,Size=size,Bytes=bytes,Touch=++touch};cacheBytes+=bytes;Render();}catch(OperationCanceledException){return;}catch(Exception){if(stamp==generation)failed.Add(request.Key);Render();}
   }}finally{pumping=false;if(!closed&&requested.Count>0)previewTimer.Start();}
  }
  sealed class CanvasTextLayout {internal string Value,Color;internal double Width,FontSize,Height;internal FormattedText Text;}
  sealed class CanvasPreview {internal BitmapSource Image;internal int Size;internal long Bytes,Touch;}
  sealed class FreeCanvasSurface:FrameworkElement {readonly FreeCanvasWindow owner;internal FreeCanvasSurface(FreeCanvasWindow owner){this.owner=owner;}protected override void OnRender(DrawingContext drawingContext){owner.Paint(drawingContext);}}
 }
